param(
    [Parameter(Mandatory=$true)][string]$ScummVM,
    [string]$RtzrmDat = "",
    [string]$ReelMagicDrivers = ""
)

$ErrorActionPreference = "Stop"
$PackageRoot = Split-Path -Parent $MyInvocation.MyCommand.Path

function Invoke-EmbeddedStage {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][string]$Data,
        [hashtable]$Parameters
    )

    Write-Host ""
    Write-Host ">>> $Name" -ForegroundColor Cyan

    $bytes = [Convert]::FromBase64String($Data)
    $source = [Text.Encoding]::UTF8.GetString($bytes)

    # Embedded stages normally only need their parameters. If a stage ever
    # references its own script directory, point it back to this flat package.
    $source = $source.Replace(
        '$root = Split-Path -Parent $MyInvocation.MyCommand.Path',
        '$root = $script:RTZPackageRoot'
    )
    $source = $source.Replace(
        '$here = Split-Path -Parent $MyInvocation.MyCommand.Path',
        '$here = $script:RTZPackageRoot'
    )

    $script:RTZPackageRoot = $PackageRoot
    $block = [ScriptBlock]::Create($source)
    & $block @Parameters
}

function Invoke-Validator {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [hashtable]$Parameters
    )

    $path = Join-Path $PackageRoot $Name
    if (-not (Test-Path $path)) {
        throw "Validator mancante: $Name"
    }

    Write-Host ">>> $Name" -ForegroundColor DarkCyan
    & $path @Parameters
    if ($LASTEXITCODE -ne 0) {
        throw "$Name fallito"
    }
}

$stages = @(
    @{ Name = 'stage1_refactor_reelmagic.ps1'; Data = ''; Validator = 'validate_refactor.ps1' },
    @{ Name = 'stage2_harden_reelmagic.ps1'; Data = ''; Validator = 'validate_decoder.ps1' },
    @{ Name = 'stage3_runtime_pause.ps1'; Data = ''; Validator = 'validate_pause.ps1' },
    @{ Name = 'stage4_runtime_trace.ps1'; Data = ''; Validator = 'validate_trace.ps1' },
    @{ Name = 'stage7_frame_rate_fix.ps1'; Data = ''; Validator = 'validate_frame_rate.ps1' },
    @{ Name = 'stage8_maderm_fidelity.ps1'; Data = ''; Validator = 'validate_maderm.ps1' },
    @{ Name = 'stage9_driver111_fidelity.ps1'; Data = ''; Validator = 'validate_driver.ps1' }
)

foreach ($stage in $stages) {
    $stageParams = @{
        ScummVM = $ScummVM
    }

    Invoke-EmbeddedStage -Name $stage.Name -Data $stage.Data -Parameters $stageParams

    $validatorParams = @{
        ScummVM = $ScummVM
    }

    if ($stage.Validator -eq 'validate_maderm.ps1' -and $RtzrmDat) {
        $validatorParams['RtzrmDat'] = $RtzrmDat
    }

    if ($stage.Validator -eq 'validate_driver.ps1') {
        if ($RtzrmDat) { $validatorParams['RtzrmDat'] = $RtzrmDat }
        if ($ReelMagicDrivers) { $validatorParams['ReelMagicDrivers'] = $ReelMagicDrivers }
    }

    Invoke-Validator -Name $stage.Validator -Parameters $validatorParams
}

# All per-stage validators have completed at this point.
# Normalize build metadata BEFORE the single cumulative final validation.
# PR #7849 places "mad" in MADE's components list, but ScummVM explicitly
# defines MAD as a global feature that cannot be a component. Other engines
# (e.g. AGS/Titanic) put mad in the dependency field instead.
Write-Host ""
Write-Host ">>> normalizzazione configure.engine MADE" -ForegroundColor Cyan
$madeConfigure = Join-Path $ScummVM "engines\made\configure.engine"
if (-not (Test-Path $madeConfigure -PathType Leaf)) {
    throw "configure.engine MADE non trovato: $madeConfigure"
}

$cfg = Get-Content $madeConfigure -Raw
$badCfg = 'add_engine made "MADE" yes "" "" "" "midi mpeg2 mad"'
$goodCfg = 'add_engine made "MADE" yes "" "" "mad" "midi mpeg2"'

if ($cfg.Contains($badCfg)) {
    $cfg = $cfg.Replace($badCfg, $goodCfg)
    $enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($madeConfigure, $cfg, $enc)
} elseif (-not $cfg.Contains($goodCfg)) {
    throw "Configurazione MADE inattesa: impossibile normalizzare deps/components."
}

Write-Host "MADE configure: mad=deps, midi+mpeg2=components OK" -ForegroundColor Green

# ReelMagic keeps SAMPLE.AD inside RTZRM.RED rather than as a loose file.
# MADE already supports passing a timbre stream to the Miles AdLib driver for
# RTZCD.RED, so extend the same native path to the ReelMagic archive.
Write-Host ""
Write-Host ">>> integrazione SAMPLE.AD da RTZRM.RED" -ForegroundColor Cyan

$musicPath = Join-Path $ScummVM "engines\made\music.cpp"
if (-not (Test-Path $musicPath -PathType Leaf)) {
    throw "music.cpp MADE non trovato: $musicPath"
}

$music = Get-Content $musicPath -Raw
$oldMusic = @'
			if (Common::File::exists("rtzcd.red")) {
				// Installing Return to Zork produces both a SAMPLE.AD and
				// a SAMPLE.OPL file, but they are identical. The resource
				// file appears to only contain SAMPLE.AD.
				adLibInstrumentStream = RedReader::loadFromRed("rtzcd.red", "SAMPLE.AD");
			}
'@
$newMusic = @'
			if (Common::File::exists("rtzcd.red")) {
				// Installing Return to Zork produces both a SAMPLE.AD and
				// a SAMPLE.OPL file, but they are identical. The resource
				// file appears to only contain SAMPLE.AD.
				adLibInstrumentStream = RedReader::loadFromRed("rtzcd.red", "SAMPLE.AD");
			} else if (Common::File::exists("rtzrm.red")) {
				// The ReelMagic release keeps SAMPLE.AD inside RTZRM.RED.
				// Pass it directly to the Miles driver as a resource stream.
				adLibInstrumentStream = RedReader::loadFromRed("rtzrm.red", "SAMPLE.AD");
			}
'@

if ($music.Contains($oldMusic)) {
    $music = $music.Replace($oldMusic, $newMusic)
    $enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($musicPath, $music, $enc)
} elseif (-not $music.Contains('RedReader::loadFromRed("rtzrm.red", "SAMPLE.AD")')) {
    throw "Blocco Miles/RTZ inatteso in music.cpp: patch RTZRM.RED non applicabile."
}

$musicCheck = Get-Content $musicPath -Raw
if (-not $musicCheck.Contains('Common::File::exists("rtzrm.red")') -or
    -not $musicCheck.Contains('RedReader::loadFromRed("rtzrm.red", "SAMPLE.AD")')) {
    throw "Supporto SAMPLE.AD da RTZRM.RED non presente dopo la patch."
}
Write-Host "MADE music: SAMPLE.AD da RTZRM.RED OK" -ForegroundColor Green

# Keep ReelMagic MPEG playback advancing even when the MADE script is not
# actively polling movie state. This is a functional runtime fix, not tracing.
Write-Host ""
Write-Host ">>> central video pump ReelMagic" -ForegroundColor Cyan

$madeCppPath = Join-Path $ScummVM "engines\made\made.cpp"
if (-not (Test-Path $madeCppPath -PathType Leaf)) {
    throw "made.cpp non trovato: $madeCppPath"
}

$enc = New-Object System.Text.UTF8Encoding($false)
$madeCpp = Get-Content $madeCppPath -Raw

if (-not $madeCpp.Contains('// RTZRM central video pump')) {
    $oldEventTail = @'
	_system->getAudioCDManager()->update();

}
'@
    $newEventTail = @'
	_system->getAudioCDManager()->update();

	// RTZRM central video pump: audio is pulled asynchronously by the mixer,
	// while MPEG video frames advance only when MpegPlayer::update() runs.
	if (_mpegPlayer)
		_mpegPlayer->update();

}
'@
    if (-not $madeCpp.Contains($oldEventTail)) {
        throw "MadeEngine::handleEvents tail inatteso: impossibile aggiungere central video pump."
    }
    $madeCpp = $madeCpp.Replace($oldEventTail, $newEventTail)
    [System.IO.File]::WriteAllText($madeCppPath, $madeCpp, $enc)
}

$madeCheck = Get-Content $madeCppPath -Raw
if (-not $madeCheck.Contains('// RTZRM central video pump') -or
    -not $madeCheck.Contains('_mpegPlayer->update();')) {
    throw "Central video pump ReelMagic non presente dopo la patch."
}

Write-Host "Central video pump ReelMagic OK" -ForegroundColor Green

# Space skips only non-looping ReelMagic cutscenes. Looping MPEG handles are
# commonly scene backgrounds/overlays and must not be killed by normal gameplay.
Write-Host ""
Write-Host ">>> SPACE skip cutscene ReelMagic" -ForegroundColor Cyan

$mpegHeaderPath = Join-Path $ScummVM "engines\made\mpegplayer.h"
$mpegCppPath = Join-Path $ScummVM "engines\made\mpegplayer.cpp"
if (-not (Test-Path $mpegHeaderPath -PathType Leaf)) { throw "mpegplayer.h non trovato" }
if (-not (Test-Path $mpegCppPath -PathType Leaf)) { throw "mpegplayer.cpp non trovato" }

$enc = New-Object System.Text.UTF8Encoding($false)

$mpegHeader = Get-Content $mpegHeaderPath -Raw
if (-not $mpegHeader.Contains("isSkippableMovieOpen()")) {
    $resumeDecl = "`tvoid resume();"
    if (-not $mpegHeader.Contains($resumeDecl)) {
        throw "Dichiarazione MpegPlayer::resume non trovata per SPACE skip."
    }

    $skipDecl = @'

	/**
	 * True while a non-looping ReelMagic movie owns the media handle.
	 * Space is consumed for the lifetime of this handle so key repeat cannot
	 * leak into gameplay immediately after a user-requested skip.
	 */
	bool isSkippableMovieOpen() const { return _decoder != nullptr && !_looping; }

	/**
	 * Completes the current non-looping movie immediately, preserving the
	 * ReelMagic pause-on-completion state expected by the game scripts.
	 */
	bool skip();
'@
    $mpegHeader = $mpegHeader.Replace($resumeDecl, $resumeDecl + $skipDecl)
    [System.IO.File]::WriteAllText($mpegHeaderPath, $mpegHeader, $enc)
}

$mpegCpp = Get-Content $mpegCppPath -Raw
if (-not $mpegCpp.Contains("bool MpegPlayer::skip()")) {
    $closeNeedle = "void MpegPlayer::close() {"
    $closePos = $mpegCpp.IndexOf($closeNeedle)
    if ($closePos -lt 0) { throw "MpegPlayer::close non trovato per SPACE skip." }

    $skipImpl = @'
bool MpegPlayer::skip() {
	// Mode 2 is normally a persistent room/background overlay. Do not let the
	// Space shortcut destroy those handles.
	if (!_decoder || _looping || _passComplete)
		return false;

	debug(1, "MpegPlayer: user skipped '%s' with Space at frame %u",
		_filename.c_str(), _framesDrawn);

	// Match the state reached by natural completion. The script sees state 2
	// (Paused), blocking waits see !isPlaying(), and VideoDecoder::pauseVideo()
	// pauses both video and MPEG audio immediately.
	_passComplete = true;
	beginFrameClockPause();
	_paused = true;
	_decoder->pauseVideo(true);
	return true;
}

'@
    $mpegCpp = $mpegCpp.Insert($closePos, $skipImpl)

    # Non-MPEG stub.
    $elsePos = $mpegCpp.IndexOf("#else", $closePos + $skipImpl.Length)
    if ($elsePos -lt 0) { throw "#else USE_MPEG2 non trovato per SPACE skip." }
    $head = $mpegCpp.Substring(0, $elsePos)
    $tail = $mpegCpp.Substring($elsePos)
    $stubAnchor = @'
void MpegPlayer::resume() {
}

void MpegPlayer::close() {
'@
    $stubReplace = @'
void MpegPlayer::resume() {
}

bool MpegPlayer::skip() {
	return false;
}

void MpegPlayer::close() {
'@
    if ($tail.Contains($stubAnchor)) {
        $tail = $tail.Replace($stubAnchor, $stubReplace)
    } elseif (-not $tail.Contains("bool MpegPlayer::skip()")) {
        throw "Stub MpegPlayer::resume inatteso per SPACE skip."
    }
    $mpegCpp = $head + $tail
    [System.IO.File]::WriteAllText($mpegCppPath, $mpegCpp, $enc)
}

$madeCppPath = Join-Path $ScummVM "engines\made\made.cpp"
$madeCpp = Get-Content $madeCppPath -Raw
if (-not $madeCpp.Contains("RTZRM SPACE skip")) {
    $keyAnchor = @'
		case Common::EVENT_KEYDOWN:
			// Handle any special keys here
'@
    $keyReplacement = @'
		case Common::EVENT_KEYDOWN:
			// RTZRM SPACE skip: consume Space while a non-looping ReelMagic
			// handle is open. Repeated keydown events therefore cannot leak into
			// gameplay after the first event marks the cutscene complete.
			if (event.kbd.keycode == Common::KEYCODE_SPACE &&
				_mpegPlayer && _mpegPlayer->isSkippableMovieOpen()) {
				_mpegPlayer->skip();
				break;
			}

			// Handle any special keys here
'@
    if (-not $madeCpp.Contains($keyAnchor)) {
        throw "EVENT_KEYDOWN anchor inatteso per RTZRM SPACE skip."
    }
    $madeCpp = $madeCpp.Replace($keyAnchor, $keyReplacement)
    [System.IO.File]::WriteAllText($madeCppPath, $madeCpp, $enc)
}

# Structural contract checks after patch.
$skipH = Get-Content $mpegHeaderPath -Raw
$skipC = Get-Content $mpegCppPath -Raw
$skipM = Get-Content $madeCppPath -Raw
foreach ($needle in @("bool isSkippableMovieOpen() const", "bool skip();")) {
    if (-not $skipH.Contains($needle)) { throw "SPACE skip header check fallito: $needle" }
}
foreach ($needle in @("bool MpegPlayer::skip()", "if (!_decoder || _looping || _passComplete)",
                       "_passComplete = true;", "_decoder->pauseVideo(true);")) {
    if (-not $skipC.Contains($needle)) { throw "SPACE skip cpp check fallito: $needle" }
}
foreach ($needle in @("RTZRM SPACE skip", "Common::KEYCODE_SPACE",
                       "_mpegPlayer->isSkippableMovieOpen()", "_mpegPlayer->skip();")) {
    if (-not $skipM.Contains($needle)) { throw "SPACE skip event check fallito: $needle" }
}
Write-Host "SPACE skip cutscene ReelMagic OK" -ForegroundColor Green

# Give the ReelMagic release a distinct launcher identity without creating a
# separate engine. Both variants still run as GID_RTZ inside MADE.
Write-Host ""
Write-Host ">>> launcher identity Return to Zork (ReelMagic)" -ForegroundColor Cyan

$detectionCppPath = Join-Path $ScummVM "engines\made\detection.cpp"
$detectionTablesPath = Join-Path $ScummVM "engines\made\detection_tables.h"
if (-not (Test-Path $detectionCppPath -PathType Leaf)) { throw "detection.cpp non trovato" }
if (-not (Test-Path $detectionTablesPath -PathType Leaf)) { throw "detection_tables.h non trovato" }

$enc = New-Object System.Text.UTF8Encoding($false)

$detectionCpp = Get-Content $detectionCppPath -Raw
if (-not $detectionCpp.Contains('{"rtzrm", "Return to Zork (ReelMagic)"}')) {
    $plainRtz = '{"rtz", "Return to Zork"},'
    if (-not $detectionCpp.Contains($plainRtz)) {
        throw "PlainGameDescriptor RTZ non trovato."
    }
    $detectionCpp = $detectionCpp.Replace(
        $plainRtz,
        $plainRtz + "`n`t" + '{"rtzrm", "Return to Zork (ReelMagic)"},'
    )
    [System.IO.File]::WriteAllText($detectionCppPath, $detectionCpp, $enc)
}

$detectionTables = Get-Content $detectionTablesPath -Raw

# Change only the two ReelMagic entries. Their internal game enum remains
# GID_RTZ and their feature flag remains GF_REELMAGIC.
$rmInstalledOld = @'
		{
			"rtz",
			"ReelMagic V1.00, 5/25/94, installed, CD",
'@
$rmInstalledNew = @'
		{
			"rtzrm",
			"ReelMagic V1.00, 5/25/94, installed, CD",
'@
if ($detectionTables.Contains($rmInstalledOld)) {
    $detectionTables = $detectionTables.Replace($rmInstalledOld, $rmInstalledNew)
} elseif (-not $detectionTables.Contains($rmInstalledNew)) {
    throw "Entry ReelMagic installed inattesa."
}

$rmPackedOld = @'
		{
			"rtz",
			"ReelMagic V1.00, 5/25/94, CD",
'@
$rmPackedNew = @'
		{
			"rtzrm",
			"ReelMagic V1.00, 5/25/94, CD",
'@
if ($detectionTables.Contains($rmPackedOld)) {
    $detectionTables = $detectionTables.Replace($rmPackedOld, $rmPackedNew)
} elseif (-not $detectionTables.Contains($rmPackedNew)) {
    throw "Entry ReelMagic packed inattesa."
}

[System.IO.File]::WriteAllText($detectionTablesPath, $detectionTables, $enc)

# Contract: exactly two rtzrm table entries, both remain GID_RTZ/GF_REELMAGIC.
$dc = Get-Content $detectionCppPath -Raw
$dt = Get-Content $detectionTablesPath -Raw
if (-not $dc.Contains('{"rtzrm", "Return to Zork (ReelMagic)"}')) {
    throw "Launcher descriptor ReelMagic non applicato."
}
$rtzrmCount = ([regex]::Matches($dt, '"rtzrm"')).Count
if ($rtzrmCount -ne 2) {
    throw "Attese esattamente 2 detection entry rtzrm, trovate $rtzrmCount."
}

$rmBlocks = [regex]::Matches(
    $dt,
    '(?s)\{\s*"rtzrm",\s*"ReelMagic V1\.00.*?\},\s*GID_RTZ,\s*0,\s*GF_[^,]*REELMAGIC[^,]*,\s*3,\s*\}'
)
if ($rmBlocks.Count -ne 2) {
    throw "Le entry rtzrm non preservano GID_RTZ/GF_REELMAGIC."
}

Write-Host "Launcher: Return to Zork (ReelMagic) [rtzrm] OK" -ForegroundColor Green

# Native ScummVM presentation:
# 1) use the software SDL renderer directly from scummvm.exe on Windows,
#    avoiding the Direct3D presentation bug proven by RTZ139/RTZ140;
# 2) map made:rtzrm to the official Return to Zork launcher icon already
#    contained in ScummVM's gui-icons.dat.
Write-Host ""
Write-Host ">>> native ScummVM presentation" -ForegroundColor Cyan

$surfaceSdlPath = Join-Path $ScummVM "backends\graphics\surfacesdl\surfacesdl-graphics.cpp"
if (-not (Test-Path $surfaceSdlPath -PathType Leaf)) {
	throw "SurfaceSDL backend non trovato: $surfaceSdlPath"
}

$surfaceSdl = Get-Content $surfaceSdlPath -Raw
if (-not $surfaceSdl.Contains("RTZRM native software renderer")) {
	$rendererAnchor = @'
#if defined(MACOSX) && SDL_VERSION_ATLEAST(2, 0, 10)
'@
	$rendererPatch = @'
#if defined(WIN32) && !SDL_VERSION_ATLEAST(3, 0, 0)
	// RTZRM native software renderer: on the tested Windows/SDL2 Direct3D
	// backend, ReelMagic frames reach the D3D render target correctly but are
	// not presented to the window. The software renderer presents the same
	// RGB565 frames correctly and still supports ScummVM scaling/filtering.
	SDL_SetHint(SDL_HINT_RENDER_DRIVER, "software");
#endif

#if defined(MACOSX) && SDL_VERSION_ATLEAST(2, 0, 10)
'@
	if (-not $surfaceSdl.Contains($rendererAnchor)) {
		throw "SurfaceSDL renderer anchor inatteso for the native build."
	}
	$surfaceSdl = $surfaceSdl.Replace($rendererAnchor, $rendererPatch)
	$enc = New-Object System.Text.UTF8Encoding($false)
	[System.IO.File]::WriteAllText($surfaceSdlPath, $surfaceSdl, $enc)
}

$gridPath = Join-Path $ScummVM "gui\widgets\grid.h"
if (-not (Test-Path $gridPath -PathType Leaf)) {
	throw "Grid launcher non trovata: $gridPath"
}
$grid = Get-Content $gridPath -Raw

if (-not $grid.Contains("RTZRM launcher icon alias")) {
	$iconAnchor = @'
		thumbPath = Common::String::format("icons/%s-%s.png", engineid.c_str(), gameid.c_str());
'@
	$iconPatch = @'
		thumbPath = Common::String::format("icons/%s-%s.png", engineid.c_str(), gameid.c_str());
		// RTZRM launcher icon alias: ReelMagic is a variant of Return to Zork,
		// so use the official made-rtz.png supplied by ScummVM's icon pack.
		if (engineid == "made" && gameid == "rtzrm")
			thumbPath = "icons/made-rtz.png";
'@
	if (-not $grid.Contains($iconAnchor)) {
		throw "GridItemInfo thumbPath anchor inatteso for the native build."
	}
	$grid = $grid.Replace($iconAnchor, $iconPatch)
	$enc = New-Object System.Text.UTF8Encoding($false)
	[System.IO.File]::WriteAllText($gridPath, $grid, $enc)
}

$surfaceCheck = Get-Content $surfaceSdlPath -Raw
$gridCheck = Get-Content $gridPath -Raw
foreach ($needle in @(
	"RTZRM native software renderer",
	'SDL_SetHint(SDL_HINT_RENDER_DRIVER, "software")'
)) {
	if (-not $surfaceCheck.Contains($needle)) {
		throw "Native SurfaceSDL check fallito: $needle"
	}
}
foreach ($needle in @(
	"RTZRM launcher icon alias",
	'engineid == "made" && gameid == "rtzrm"',
	'thumbPath = "icons/made-rtz.png"'
)) {
	if (-not $gridCheck.Contains($needle)) {
		throw "Native launcher icon check fallito: $needle"
	}
}

Write-Host "Native launcher + renderer software + icona ufficiale RTZ OK" -ForegroundColor Green

Write-Host ""
Write-Host ">>> final validation" -ForegroundColor DarkCyan
$finalParams = @{ ScummVM = $ScummVM }
& (Join-Path $PackageRoot 'validate_final.ps1') @finalParams
if ($LASTEXITCODE -ne 0) {
    throw "validate_final.ps1 fallito"
}

Write-Host ""
Write-Host "RTZ ReelMagic compatibility: patch ReelMagic applicate e validate." -ForegroundColor Green
